const $=s=>document.querySelector(s),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const button=a=>`[data-deck="0"][data-action="${a}"]`,click=s=>{assert($(s),'Missing '+s);$(s).click();};
const files=['app.js','engine.js','stems.js','panels.js','keylock.js','keylock-worker.js','keylock-dsp.js','smart-sync.js','beatgrid.js','warp-loop.js','warp-loop-kernel.js','warp-loop-worklet.js','reverse-censor-plan.js','stem-reverse-161-harness.js','stem-activation-capture-145.js','stem-history-worklet.js','keylock-shadow-live.js','vendor/signalsmith-stretch/SignalsmithStretch-open-play-replace.mjs','vendor/signalsmith-stretch/SignalsmithStretch-open-play-reference-dsp.mjs'];
const sha=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');
async function identities(){return Object.fromEntries(await Promise.all(files.map(async f=>{const response=await fetch(f,{cache:'no-store'});assert(response.ok,f);return[f,await sha(await response.arrayBuffer())];})));}
async function until(fn,label,ms=30000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function input(selector,value){const element=$(selector);assert(element,'Missing '+selector);element.value=String(value);element.dispatchEvent(new Event('input',{bubbles:true}));}
function base64(bytes){let value='';for(let i=0;i<bytes.length;i+=16384)value+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(value);}
let app,readiness;
async function run(){
 clearInterval(readiness);$('#music-run').disabled=true;
 const {engine,state}=app,deck=state.decks[0],witnesses=[];
 const selectedOnly=true;
 const r={checkpoint:150,diagnosticCheckpoint:161,variant:'warped-reverse-loop-exit',samples:[],startedAt:new Date().toISOString(),scope:'Actual MP3/real cached SCNet/grid/Sync/Q/Loop-off, ordinary non-loop reverse, forward return, source-start end and Stop; raw and keylock-key3. Physically muted internal PCM. Exact Serato composition/pitch/quality/native/hardware/full parity unverified.',criteria:{minimumRMS:1e-5,maximumStoppedPeak:1e-7,sourceClockErrorSeconds:.01,rawComparisonWindow:[.3,1.3],maximumRawRelativeRMS:1e-4},stages:[],progress:[],errors:[]};let observer,original,track;
 async function pause(){if(deck.playing)click(button('play'));await until(()=>!deck.playing&&!deck.processing,'Pause');}
 async function seekOne(){const el=$('[data-seek="0"]');assert(el,'Actual seek overview');el.dispatchEvent(new KeyboardEvent('keydown',{key:'Home',bubbles:true}));await until(()=>Math.abs(engine.position(deck))<1e-8&&!deck.processing,'Seek Home');el.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));await until(()=>Math.abs(engine.position(deck)-1)<1e-8&&!deck.processing,'Seek one second');}
 function mask(values){for(let p=0;p<4;p++)if(deck.stems[p]!==values[p])click(button('pad')+`[data-pad="${p}"]`);assert(JSON.stringify(deck.stems)===JSON.stringify(values),'Actual pad mask');}
 function capture(){return Promise.all(witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM timeout')),15000);w.port.onmessage=({data})=>{if(data.type==='done'){clearTimeout(timer);resolve(data);}};w.port.postMessage({type:'capture',id:'reverse161',frames:Math.round((r.captureSeconds||2)*engine.ctx.sampleRate)});})));}
 async function retain(packets){return Promise.all(packets.map(async(p,c)=>({channel:c,startFrame:p.startFrame,frames:p.data.length,quanta:p.quanta,errors:p.errors,sha256:await sha(p.data.buffer),base64:base64(new Uint8Array(p.data.buffer))})));}
 async function stage(name,values){
  await pause();mask(values);await seekOne();click(button('play'));await until(()=>deck.playing&&!deck.processing,'Play '+name);await sleep(200);
  const voice=engine.voices.get(0),row={name,mask:[...deck.stems],rate:deck.rate,keylock:deck.keylock,keyShift:deck.keyShift,anchorTime:deck.anchorTime,anchorPosition:deck.anchorPosition,at:engine.ctx.currentTime,gains:voice.stemGains.map(g=>g.gain.value),live:voice.liveKeylock?.snapshot()||null};r.stages.push(row);
  row.pcm=await retain(await capture());await pause();
 }
 try{
  r.sourceBefore=await identities();await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical mute required');
  track=state.tracks.find(t=>t.file?.name==='SDRNR-private-research-159.mp3');assert(track?.contentHash==='cb2e756d1fa4ce264767a4f6adbaf9e3f69a040db7889d830abdb429cc1a5ac3','Actual expected imported file');await until(()=>!state.analysis&&$('#analyze').textContent==='Analyze','Imported analysis');
  r.import={id:track.id,contentHash:track.contentHash,filename:track.file.name,bytes:track.file.size,type:track.type,storage:track.storage,duration:track.duration};click(`[data-track="${track.id}"]`);click(button('load'));await until(()=>deck.track===track&&!deck.processing,'Actual deck Load');
  original=await engine.buffer(track);r.input={frames:original.length,sampleRate:original.sampleRate,channels:original.numberOfChannels,duration:original.duration};assert(track.duration===original.duration&&original.duration>3.5,'Imported duration');r.originalHashes=await Promise.all([0,1].map(c=>sha(original.getChannelData(c).buffer)));
  assert(deck.rate===1&&!deck.keylock&&!deck.keyShift&&!deck.loop&&!deck.reverse&&!deck.sync,'Neutral loaded transport');assert(state.fx.every(unit=>unit.every(slot=>!slot.on))&&deck.stemFX.every(v=>!v),'No FX');
  for(const k of ['low','mid','high','filter'])input(`[data-mix="0:${k}"]`,0);input('[data-track-gain="0"]',0);await sleep(250);
  click(button('tab')+'[data-tab="Stems"]');click(button('stemPrepare'));const output=$('#stems-state');observer=new MutationObserver(()=>{r.progress.push({at:performance.now(),text:output.textContent});$('#music-status').textContent=output.textContent;});observer.observe(output,{childList:true,subtree:true,characterData:true});click('#stems-queue');await until(()=>!$('#stems-queue').disabled&&/^(Ready|Failed)/.test(track.stemState),'Actual musical preparation',120000);assert(track.stemState.startsWith('Ready'),track.stemState);
  r.ready={status:output.textContent,job:track.stemJob,model:track.stemModel,buffers:engine.stemBuffers.get(track.id).map(b=>({frames:b.length,sampleRate:b.sampleRate,channels:b.numberOfChannels,duration:b.duration}))};const response=await fetch('/api/stems/'+track.stemJob);assert(response.ok,'Real job');r.job=await response.json();assert(r.job.state==='complete'&&r.job.model==='SCNet-large official','Actual real separation');assert(r.ready.buffers.length===4&&r.ready.buffers.every(b=>b.frames===original.length&&b.channels===2&&b.sampleRate===original.sampleRate),'Actual output lengths');click('#modal-close');
  await engine.ctx.audioWorklet.addModule(new URL('./stem-activation-capture-145.js',import.meta.url));const split=engine.ctx.createChannelSplitter(2);engine.nodes[0].monitorTap.connect(split);for(let c=0;c<2;c++){const w=new AudioWorkletNode(engine.ctx,'open-play-stem-activation-145-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(w,c);w.connect(engine.ctx.destination);witnesses.push(w);}r.sampleRate=engine.ctx.sampleRate;
  click(button('grid'));$('#grid-bpm').value='120';$('#grid-offset').value='0';click('#grid-clear');for(const marker of [{time:1,bpm:150},{time:1.8,bpm:90}]){$('#grid-warp-time').value=marker.time;$('#grid-warp-bpm').value=marker.bpm;click('#grid-marker');}click('#grid-save');await until(()=>!$('#modal').open,'Save grid');
  click('[data-panel="settings"]');const setting=$('[data-setting="Sync Mode"]');setting.value='Smart Sync';setting.dispatchEvent(new Event('change',{bubbles:true}));click('#save-settings');
  async function seek(position){const el=$('[data-seek="0"]'),box=el.getBoundingClientRect();el.dispatchEvent(new MouseEvent('click',{clientX:box.left+position/track.duration*el.clientWidth,clientY:box.top+20,bubbles:true}));await until(()=>Math.abs(engine.position(deck)-position)<.01&&!deck.processing,'Seek '+position);}
  click(button('tab')+'[data-tab="Stems"]');mask([false,true,true,true]);r.grid={bpm:track.bpm,offset:track.grid,markers:track.gridWarpMarkers};
  async function probe(name,seconds){r.captureSeconds=seconds;const voice=engine.voices.get(0),row={name,mask:[...deck.stems],rate:deck.rate,keylock:deck.keylock,keyShift:deck.keyShift,reverse:deck.reverse,syncState:deck.syncState,anchorTime:deck.anchorTime,anchorPosition:deck.anchorPosition,at:engine.ctx.currentTime,gains:voice.stemGains.map(g=>g.gain.value),warpLoop:!!voice.warpLoopTransport,live:voice.liveKeylock?.snapshot()||null,loop:deck.loop,positions:[]};r.stages.push(row);const timer=setInterval(()=>row.positions.push({at:engine.ctx.currentTime,position:engine.position(deck),rate:engine.audibleRate(deck),playing:deck.playing}),50);try{row.pcm=await retain(await capture());}finally{clearInterval(timer);}row.after={position:engine.position(deck),playing:deck.playing,voice:!!engine.voices.get(0)};}
  const reverse=()=>{document.body.dispatchEvent(new KeyboardEvent('keydown',{key:'Q',code:'KeyQ',shiftKey:true,bubbles:true,cancelable:true}));document.body.dispatchEvent(new KeyboardEvent('keyup',{key:'q',code:'KeyQ',bubbles:true,cancelable:true}));};
  for(const cfg of [{name:'raw',keylock:false,key:0},{name:'keylock-key3',keylock:true,key:3}]){
   await pause();if(deck.reverse){reverse();await until(()=>!deck.reverse&&!deck.processing,'Forward while paused');}if(deck.keylock!==cfg.keylock){click(button('keylock'));await until(()=>deck.keylock===cfg.keylock&&!deck.processing,'Keylock');}while(deck.keyShift<cfg.key){click(button('keyUp'));await until(()=>!deck.processing,'Key shift');}
   await seek(0);click(button('loopIn'));await sleep(50);await seek(1.8+8/3);click(button('loopOut'));await until(()=>deck.loop&&!deck.processing,'Manual loop');await seek(0);click(button('sync'));await until(()=>deck.sync,'Arm Sync');r.loopBounds={start:deck.loopIn,end:deck.loopOut};await seek(4);click(button('play'));await until(()=>deck.playing&&!deck.processing,'Forward play');await sleep(100);reverse();await until(()=>deck.reverse&&deck.playing&&!deck.processing,'Loop reverse');r.beforeExit={position:engine.position(deck),reverse:deck.reverse,loop:deck.loop,playing:deck.playing};click(button('loop'));await until(()=>!deck.loop&&deck.playing&&!deck.processing,'Loop exit while reverse',10000);await probe(cfg.name+'-loop-exit-reverse',2);
   reverse();await until(()=>!deck.reverse&&deck.playing&&!deck.processing,'Return forward');await probe(cfg.name+'-forward-return',2);await pause();await seek(1.5);reverse();await until(()=>deck.reverse&&!deck.processing,'Ordinary reverse armed');click(button('play'));await until(()=>deck.playing&&!deck.processing,'Ordinary reverse Play');await probe(cfg.name+'-natural-start',3);assert(!deck.playing&&Math.abs(engine.position(deck))<1e-7,'Reverse must end at original0');
  }
  reverse();await until(()=>!deck.reverse&&!deck.processing,'Final forward');await seek(1);click(button('play'));await until(()=>deck.playing&&!deck.processing,'Final Play');await sleep(200);r.captureSeconds=2;const control=capture();await sleep(300);r.stopAt=engine.ctx.currentTime;await pause();r.controlPCM=await retain(await control);
  r.originalUnchanged=JSON.stringify(r.originalHashes)===JSON.stringify(await Promise.all([0,1].map(c=>sha(original.getChannelData(c).buffer))));r.importedFileUnchanged=await sha(await track.file.arrayBuffer())===r.import.contentHash;assert(r.originalUnchanged&&r.importedFileUnchanged,'Imported audio mutated');r.workflowExecuted=true;
 }catch(error){r.errors.push({message:error.message,stack:error.stack});r.failureState={reverse:deck.reverse,playing:deck.playing,loop:deck.loop,syncState:deck.syncState,notifications:document.body.innerText.slice(-2400)};}
 finally{
  observer?.disconnect();for(const d of state.decks)engine.pause(d);for(const w of witnesses){w.disconnect();w.port.close();}r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.workflowCompleted=!!r.workflowExecuted&&!r.errors.length&&r.sourceStable;r.finishedAt=new Date().toISOString();const raw=JSON.stringify(r),id=crypto.randomUUID().replaceAll('-','');let receipt;
  try{const response=await fetch('/api/test-evidence/stem-resource-150/'+id,{method:'POST',headers:{'Content-Type':'application/json','X-Open-Play':'local-prototype'},body:raw});assert(response.ok,'Save failed');receipt=await response.json();const bytes=new TextEncoder().encode(raw);assert(receipt.bytes===bytes.length&&receipt.sha256===await sha(bytes),'Receipt mismatch');}catch(error){receipt={id,error:error.message};const link=$('#music-download');link.href=URL.createObjectURL(new Blob([raw],{type:'application/json'}));link.download=id+'.json';link.hidden=false;}
  const summary={workflowCompleted:r.workflowCompleted,sourceStable:r.sourceStable,import:r.import,input:r.input,ready:r.ready,stages:r.stages.map(s=>({name:s.name,mask:s.mask,rate:s.rate,keylock:s.keylock,keyShift:s.keyShift,reverse:s.reverse,syncState:s.syncState})),errors:r.errors,receipt};$('#music-original').textContent=JSON.stringify(summary);$('#music-results').textContent=JSON.stringify(summary,null,2);$('#music-status').textContent=r.workflowCompleted?'Loop-exit workflow recorded; stopped; independent inspection pending':'Failed workflow retained';
 }
}
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'App');app=window.openPlay;app.engine.init();app.engine.audioMonitor.mutePhysical(true);$('#music-status').textContent='Import the private research MP3 using Import audio below';readiness=setInterval(()=>{if(app.state.tracks.some(t=>t.file?.name==='SDRNR-private-research-159.mp3')){$('#music-run').disabled=false;$('#music-status').textContent='Imported file available; ready';}},250);}
$('#music-run').onclick=()=>run();boot().catch(error=>$('#music-status').textContent=error.message);
